        emon.Testport.assertEq(Fx.fxAtan2(Fx.fxOfInt(1), Fx.fxOfInt(-1)), 13500, "135");
        emon.Testport.assertEq(Fx.fxAtan2(Fx.fxOfInt(-1), Fx.fxOfInt(-1)), 22500, "225");
